package com.enterprise.fraud.entity;

import jakarta.persistence.*;
import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDateTime;

/**
 * JPA Entity representing a fraud alert generated by the ML scoring pipeline.
 * Links to a Transaction and stores the prediction result and risk assessment.
 */
@Entity
@Table(name = "fraud_alerts", indexes = {
    @Index(name = "idx_alert_status", columnList = "status"),
    @Index(name = "idx_alert_risk_score", columnList = "riskScore"),
    @Index(name = "idx_alert_timestamp", columnList = "alertTimestamp")
})
public class FraudAlert {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @NotNull(message = "Transaction reference is required")
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "transaction_id", nullable = false)
    private Transaction transaction;

    @NotNull(message = "Risk score is required")
    @DecimalMin(value = "0.0", message = "Risk score must be between 0 and 1")
    @DecimalMax(value = "1.0", message = "Risk score must be between 0 and 1")
    @Column(nullable = false)
    private Double riskScore;

    @NotNull(message = "Prediction is required")
    @Column(nullable = false)
    private Boolean prediction; // true = fraud, false = legitimate

    @NotNull(message = "Model used is required")
    @Column(nullable = false, length = 100)
    private String modelUsed;

    @NotNull
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private AlertStatus status = AlertStatus.PENDING;

    @Column(nullable = false, updatable = false)
    private LocalDateTime alertTimestamp;

    @Column
    private LocalDateTime reviewedAt;

    @Column(length = 500)
    private String reviewNotes;

    @PrePersist
    protected void onCreate() {
        this.alertTimestamp = LocalDateTime.now();
    }

    // ==================== Alert Status Enum ====================

    public enum AlertStatus {
        PENDING,
        REVIEWED,
        CONFIRMED_FRAUD,
        DISMISSED
    }

    // ==================== Getters & Setters ====================

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public Transaction getTransaction() { return transaction; }
    public void setTransaction(Transaction transaction) { this.transaction = transaction; }

    public Double getRiskScore() { return riskScore; }
    public void setRiskScore(Double riskScore) { this.riskScore = riskScore; }

    public Boolean getPrediction() { return prediction; }
    public void setPrediction(Boolean prediction) { this.prediction = prediction; }

    public String getModelUsed() { return modelUsed; }
    public void setModelUsed(String modelUsed) { this.modelUsed = modelUsed; }

    public AlertStatus getStatus() { return status; }
    public void setStatus(AlertStatus status) { this.status = status; }

    public LocalDateTime getAlertTimestamp() { return alertTimestamp; }
    public void setAlertTimestamp(LocalDateTime alertTimestamp) { this.alertTimestamp = alertTimestamp; }

    public LocalDateTime getReviewedAt() { return reviewedAt; }
    public void setReviewedAt(LocalDateTime reviewedAt) { this.reviewedAt = reviewedAt; }

    public String getReviewNotes() { return reviewNotes; }
    public void setReviewNotes(String reviewNotes) { this.reviewNotes = reviewNotes; }

    @Override
    public String toString() {
        return "FraudAlert{id=" + id + ", riskScore=" + riskScore +
               ", prediction=" + prediction + ", modelUsed='" + modelUsed +
               "', status=" + status + ", alertTimestamp=" + alertTimestamp + "}";
    }
}
